) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Дамп данных таблицы `card_decides`
--

INSERT INTO `card_decides` (`id`, `question`, `answer`, `explanation`, `points`, `created_at`, `updated_at`) VALUES
(1, 'Мастерица связала свитер и продала его за 100 руб. Какую прибыль она получила, если на свитер пошло три мотка шерсти по 20 руб. за моток, а на украшения свитера понадобился бисер стоимостью 10 руб.', '30 рублей', NULL, 40, '2025-05-22 10:36:09', '2025-05-22 12:10:59'),
(2, 'Два бизнесмена поспорили: кто получил больше прибыли. Один выручил от продажи своих товаров 5000 р., а его расходы составили 3000 р. Другой наторговал на 1000р. меньше, и затратил своих денег всего 2000 р. \nКто выиграл спор?', 'Никто', NULL, 40, '2025-05-22 12:11:28', '2025-05-22 12:11:49'),
(3, 'Костюм стоит 110 долларов. Сколько франков надо заплатить за этот костюм, если курс франка по отношению к доллару составляет 5,5? Т.е. 1 доллар=5,5 франков.', '605 франков', NULL, 40, '2025-05-22 12:11:44', '2025-05-22 12:11:44'),
(4, 'Два друга решили заработать. Они купили в киоске 100 газет по 3 руб. за газету и стали продавать их по 5 руб. за штуку. Какой доход получат ребята, когда продадут все газеты?', '200 рублей', NULL, 40, '2025-05-22 12:12:07', '2025-05-22 12:12:07'),
(5, 'Лиса купила у пчел 100 кг меда за 1000 руб., а на рынке стала продавать его по 12 руб. за кг. Какой доход получит лиса, когда продаст весь мед?', '200 рублей', NULL, 40, '2025-05-22 12:12:19', '2025-05-22 12:12:19'),
(6, 'Коля печет пирожки и продает их на рынке. В первый день он продал 100 пирожков по цене 1 руб. за один пирожок. На следующий день он снизил цену на 10% и продал 110 пирожков. В какой день он заработал больше денег?', 'В первый день', NULL, 40, '2025-05-22 12:12:34', '2025-05-22 12:12:34'),
(7, 'Вам необходимо продемонстрировать свои умения работать с числами и решить математический пример:\n\n109987 + 259259 ÷ 11 – 340980 × 10% + 10 – 99468 = ???', '0', NULL, 40, '2025-05-22 12:12:47', '2025-05-22 12:12:47'),
(8, 'Выручка от продажи продукции, выпускаемой неким предприятием, составила 50000руб. При этом было израсходовано:\n- На сырье – 20000 руб.\n- На топливо – 1500 руб.\n- Зарплата – 14500 руб.\n- Кредиты, налоги - 4500 руб.\n\n**Какова прибыль предприятия?**', '9500 рублей', NULL, 40, '2025-05-22 12:13:14', '2025-07-01 11:01:49'),
(9, 'В ваш банк положили 500000 р. под 10% годовых. Какую сумму денег вы сможете отдать обратно через полгода?', '525000 рублей', NULL, 40, '2025-05-22 12:13:33', '2025-05-22 12:13:33'),
(10, 'В ваш банк положили 500000 р. под 10% годовых. Какую сумму денег вы сможете отдать через 5 лет?', '~805255 рублей', NULL, 40, '2025-05-22 12:13:53', '2025-05-22 12:13:53'),
(11, 'Маша получает 500 руб. в неделю на карманные расходы. Она тратит:\nНа обеды в школе: 200 руб.\nНа проезд: 100 руб.\nНа кино: 150 руб.\nСколько денег у нее останется через 2 недели, если она откладывает все, что не потратит?', '100 рублей', '__Решение:__ \n1. 500 – (200+100+15)=50 руб./неделя. \n2. За 2 недели: 50×2=100 руб.', 40, '2025-05-22 12:14:29', '2025-05-22 12:16:30'),
(12, 'Ученики 7 класса организовали ярмарку, где продавали handmade-браслеты. \n- Количество проданных браслетов: 50 штук.  \n- Цена одного браслета: 120 рублей.  \n- Себестоимость материалов на один браслет: 80 рублей.  \n\nКакова общая выручка класса от продажи браслетов и прибыль?', '2000 рублей', '__Решение:__ \n1. Выручка = Количество × Цена = 50 × 120 = 6000 рублей.  \n2. Прибыль = Выручка − (Количество × Себестоимость) = 6000 − (50 × 80) = 6000 − 4000 = 2000 рублей.', 40, '2025-05-22 12:14:57', '2025-05-22 12:16:20'),
(13, 'Ученики 6 класса провели мастер-класс, где продавали наборы для создания новогодних открыток.\n- Количество проданных наборов: 40 штук  \n- Цена одного набора: 200 рублей  \n- Себестоимость материалов на один набор: 120 рублей.  \n- Расходы на рекламу (плакаты и объявления): 800 рублей (фиксированная сумма). \n\n__Вопросы:__\n1. Чему равна выручка от продажи наборов? \n2. Какую прибыль получил класс, если учесть все расходы?', '2400 рублей', '__Решение:__ \n1. Выручка = Количество × Цена = 40 × 200 = 8000 рублей \n2. Общие затраты = (Количество × Себестоимость) + Реклама = (40 × 120) + 800 = 4800 + 800 = 5600 рублей \n   Прибыль = Выручка − Затраты = 8000 − 5600 = 2400 рублей', 40, '2025-05-22 12:16:01', '2025-05-22 12:16:01');

