INSERT INTO `card_questions` (`id`, `question`, `answer`, `explanation`, `points`, `created_at`, `updated_at`) VALUES
(1, 'Иван Петров устраивается на работу в ООО «СтройМастер» на должность мастера-отделочника. По трудовому договору его зарплата делится на две части, одну из которых он будет получать 20-го числа каждого месяца. Как называется эта часть зарплаты?', 'Аванс', '__Аванс__ — это часть зарплаты, а не беспроцентный займ. Аванс не облагается НДФЛ. \nНалог удерживается при выплате основной части зарплаты', 50, '2025-05-22 10:34:46', '2025-05-22 12:04:47'),
(2, 'Как называются деньги в международном обращении?', 'Валюта', NULL, 50, '2025-05-22 11:35:40', '2025-05-22 11:35:40'),
(3, 'Термин «бухгалтер» появился в XV веке. Человеком, который, первым в мире получил звание бухгалтер, стал делопроизводитель Инсбрукской счетной палаты, Христофор Штехер.  А как называлась профессия бухгалтера в древности?', 'Писец или счетовод', NULL, 50, '2025-05-22 11:36:22', '2025-05-22 11:36:22'),
(4, 'В бухгалтерском учете есть два ключевых термина, которые буквально переводятся как «я верю» и «я должен». Что это за термины?', 'Дебет и Кредит', '__Дебет (лат. \"debet\" — «он должен»)__ — в бухгалтерии: __«Мне должны»__ (актив). \n- Пример: компания получает деньги от клиента.\n\n__Кредит (лат. \"credit\" — «он верит»).__ — в бухгалтерии: __«Я должен»__ (обязательство). \n- Пример: компания берёт кредит в банке.', 50, '2025-05-22 11:50:16', '2025-05-22 12:03:56'),
(5, 'Как называется «экономическая порода» собак', 'Такса', '__Такса__ — точно установленная расценка товаров или размер оплаты за тот или иной труд, услуги', 50, '2025-05-22 11:50:43', '2025-05-22 12:04:39'),
(6, 'В текущем месяце Петр ожидал получения зарплаты и процентов по вкладу. Он отложил определенную сумму на оплату коммунальных услуг, на продукты, одежду и абонемент в тренажерный зал. После всех этих трат Петр рассчитал, что останутся деньги еще и на непредвиденные нужды. Что распланировал Петр', 'Бюджет', '__Бюджет__ — план доходов и расходов на определенный период времени', 50, '2025-05-22 11:51:01', '2025-05-22 12:04:32'),
(7, 'Мария решила открыть кофейню. Она вложила 500000 руб. в ремонт помещения, покупку оборудования и обучение бариста. Ежемесячная прибыль поле вычета расходов составляла 70000 руб. Примерно через 7 месяцев Мария окупила вложения и начала получать чистый доход. Как называется такой процесс вложения денег', 'Инвестиция', '__Инвестиция__ — процесс вложения денег в акции, проекты, бизнес или себя, с целью получения прибыли в будущем', 50, '2025-05-22 11:51:30', '2025-05-22 12:04:26'),
(8, 'Как называется установленная стоимость товара или услуги', 'Цена', NULL, 50, '2025-05-22 11:52:24', '2025-05-22 11:52:24'),
(9, 'Как называется организация, которая занимается производством товаров или услуг с целью получения прибыли', 'Фирма', NULL, 50, '2025-05-22 11:52:42', '2025-05-22 11:52:42'),
(10, 'Компания «ЭлектроТех» - производитель бытовой техники (холодильники, стиральные машины). На складе, где хранится бытовая техника, произошло короткое замыкание. Сгорело более 100 холодильников. Ущерб составил 5 млн. руб., к чему руководство компании готово не было. Что необходимо было предпринять, чтобы оградить компанию от риска случайной гибели продукции?', 'Страхование', '__Страхование__ — это «финансовая подушка» для бизнеса, которая помогает пережить непредвиденные потери без катастрофических убытков', 50, '2025-05-22 11:53:19', '2025-05-22 12:04:56'),
(11, 'В начале 2020 года с полок магазинов пропали гречка, антисептики и маски. Люди стояли в очередях или приобретали по завышенным ценам у перекупщиков. Каким экономическим термином называется такая ситуация?', 'Дефицит', '__Дефицит__ — недостаток определенных товаров, услуг или ресурсов на рынке, а желающих купить - много', 50, '2025-05-22 11:53:46', '2025-05-22 12:05:04'),
(12, 'Как называется ситуация, при которой одна компания, не имеющая конкурентов, контролирует весь рынок? Например, РЖД – оператор железных дорог в России', 'Монополия', NULL, 50, '2025-05-22 11:54:07', '2025-05-22 11:54:07'),
(13, 'Экономический показатель, измеряющий эффективность получения финансового результата', 'Рентабельность', NULL, 50, '2025-05-22 11:54:23', '2025-05-22 11:54:23'),
(14, 'Фрагмент сказки братьев Гримм __«Горшочек каши»__.\n__Сюжет:__ девочка пошла в лес за ягодами и встретила там старушку. Та попросила у неё ягод, девочка их дала. Старушка поела ягоды и сказала: «Ты мне ягод дала, а я тебе тоже что-то подарю. Вот тебе горшочек». Горшочек был волшебным: стоило сказать: «Раз, два, три, Горшочек, вари!», как он начинал варить вкусную сладкую кашу, а если сказать: «Раз, два, три, больше не вари!», то горшочек переставал варить…\n__Вопрос:__ каким экономическим термином называется обмен, произведенный между девочкой и старушкой?', 'Бартер', '__Бартер__ — обмен товаров и услуг без использования денег– натуральный обмен', 50, '2025-05-22 11:55:06', '2025-05-22 12:05:10'),
(15, 'Иван всегда покупает сыр местного производства за 250 рублей в магазине у дома. Когда в очередной раз Иван зашел в магазин, он увидел, что за пачку сыра теперь нужно заплатить уже 300 рублей. При этом сам сыр остался прежним: та же фирма, состав, производство того же молочного завода. Выросла только цена.  Как называется такая экономическая ситуация?', 'Инфляция', '__Инфляция__ — это процесс обесценивания денег, при котором цены на товары и услуги растут. Проще говоря, на ту же сумму денег со временем можно купить всё меньше', 50, '2025-05-22 11:55:39', '2025-05-22 12:05:17'),
(16, 'Российская компания “РосТекстиль” закупает ткань для производства одежды из немецкой компании “Deutsches Textilhaus”. Отшивает одежду на собственных фабриках и поставляет готовую продукцию в различные магазины по всей России. Каким экономическим термином называется данная ситуация?', 'Импорт', NULL, 50, '2025-05-22 11:55:52', '2025-05-22 11:55:52'),
(17, 'Российская компания “Сибирский Лес” поставляет пиломатериалы (доску) итальянской компании “Legno Italiano”. Каким экономическим термином называется данная ситуация?', 'Экспорт', NULL, 50, '2025-05-22 11:56:26', '2025-05-22 11:56:26'),
(18, 'Компания «СтройГрад» - строительная фирма, возводившая жилые дома - брала крупные подряды, участвовала в государственных тендерах. Рассчитывая на прибыль от новых объектов, брала кредиты на технику и материалы. Однако, из-за проблем с разрешениями и проверками, задержками оплаты от заказчиков, выросшими процентами по кредитам, стройку заморозили.  Банк подал в суд за неуплату. Активы компании распродали, частично погасили долги. Компания закрылась. Люди остались без работы. Что случилось с компанией?', 'Обанкротилась', '__Банкротство__ — финансовое состояние, при котором человек или организация не могут выплатить свои долги', 50, '2025-05-22 11:56:56', '2025-05-22 12:05:24'),
(19, 'Алексей работает менеджером по продажам в компании. В этом месяце он выполнил план на 150% - привлек 10 новых клиентов вместо запланированных 6 и увеличил выручку отдела. В конце месяца Алексей получил выплату, стимулирующую сотрудников добросовестно выполнять плановые задачи или даже делать что-то сверх плана. \nЧто получил Алексей?', 'Премия', NULL, 50, '2025-05-22 11:57:33', '2025-05-22 11:57:33'),
(20, 'Есть такая пословица «Делить шкуру неубитого медведя». Каким термином можно объяснить ее значение с точки зрения бизнеса?', 'Планирование', NULL, 50, '2025-05-22 11:57:56', '2025-05-22 11:57:56'),
(21, 'В 1949 году американский бизнесмен Фрэнк Макнамара отправился в нью-йоркский ресторан со своими друзьями. Но Фрэнк не смог оплатить свой ужин, так как бумажник забыл в кармане другого пиджака. Это очень сильно его расстроило. Однако, эта ситуация натолкнула его на мысль создать… Как вы думаете, что придумал Фрэнк Макнамара?', 'Кредитные карты', NULL, 50, '2025-05-22 11:58:16', '2025-05-22 11:58:16'),
(22, 'В городе N есть пекарня «Вкусняшка» - успешная, с узнаваемым названием, рецептами и стилем. Господин Х заплатил «хозяину» данной пекарни определенную сумму, чтобы открыть такую же пекарню в другом городе. Взамен получил готовый бизнес-план, проверенных партнеров, рекламу и поддержку, а также возможность обучения. Пекарня стала приносить Господину Х прибыль, часть которой он вынужден платить «хозяину» пекарни. Как называется такой принцип работы?', 'Франшиза', '__Франшиза__ — «аренда» успешной бизнес-модели, право работать под известным брендом за плату', 50, '2025-05-22 11:58:43', '2025-05-22 12:05:32'),
(23, 'Как называется бизнес, принадлежащий одному человеку?', 'ИП, индивидуальный предприниматель', '__ИП__ — индивидуальный предприниматель', 50, '2025-05-22 11:59:21', '2025-05-22 12:05:40'),
(24, 'В м/ф «Чиполлино» Джанни Родари Принц Лимон обязал всех жителей оплачивать пользование воздухом, осадками и прочим, так как доходы государства уменьшились. Как называются такие платежи?', 'Налоги', '__Налоги__ — обязательные платежи граждан и организаций государству', 50, '2025-05-22 11:59:49', '2025-05-22 12:04:16'),
(25, 'Какое слово означает и маркетинговое предложение, и долю в бизнесе?', 'Акции', '__Акции__ —  ценные бумаги, дающие право на долю в компании', 50, '2025-05-22 12:00:46', '2025-05-22 12:03:30'),
(26, 'Как называется борьба между экономическими субъектами за максимально эффективное использование факторов производства, при единых правилах для всех ее участников', 'Конкуренция', NULL, 50, '2025-05-22 12:01:03', '2025-05-22 12:01:03'),
(27, 'Как в прошлом назывались люди, предоставляющие денежные средства в долг под начисление процентов?', 'Ростовщики', NULL, 50, '2025-05-22 12:01:15', '2025-05-22 12:01:15'),
(28, 'Какую тару образуют акции предприятия, принадлежащие одному владельцу/находящиеся в собственности инвестора?', 'Пакет', NULL, 50, '2025-05-22 12:01:30', '2025-05-22 12:01:30'),
(29, 'В к/ф «Служебный роман» сотрудники проводят плановую проверку имущества, пересчитывая и фиксируя мебель, сувениры, канцелярские принадлежности и прочее. Как называется такая проверка?', 'Инвентаризация', '__Инвентаризация__ — способ проверки фактического наличия ценностей, путем пересчета, взвешивания', 50, '2025-05-22 12:01:48', '2025-05-22 12:04:04'),
(30, 'Большинство социологов считают профессию бухгалтер одной из самых опасных и ставят ее в один ряд с такими профессиями как, пожарный, полицейский и летчик. Как вы думаете, с чем это связано?', 'Привлечение преступников', 'С тем, что сфера, в которой вращаются ресурсы и капиталы привлекает огромное количество преступников: \n- грабителей;\n- мошенников;\n- аферистов;', 50, '2025-05-22 12:02:45', '2025-05-22 12:02:45'),
(31, 'Компания “Уютный дом”, занимающаяся производством и продажей мебели, в течение нескольких лет демонстрировала стабильный рост прибыли и привлекала инвестиции. Акционеры решили продать компанию. Потенциальные покупатели, прежде чем инвестировать свои средства, провели независимую проверку финансовой отчетности компании. В результате этой проверки выяснилось, что часть сделок проводилась “мимо кассы”, а неучтенные наличные деньги присваивались руководством; в штате числились сотрудники, которые фактически не работали, а зарплата начислялась и переводилась на подконтрольные директору счета; компания завышала стоимость готовой продукции и материалов на складе, чтобы улучшить показатели баланса, создавались фиктивные счета-фактуры от подставных компаний и т.д..\nКак называется такая проверка?', 'Аудит', '__Аудит__ — это независимая проверка финансовой деятельности компании, чтобы убедиться в ее честности, правильности и надежности', 50, '2025-05-22 12:03:20', '2025-05-22 12:03:20'),
(32, 'В бухгалтерском балансе существует две составляющие: активы и пассивы. Простыми словами «активы» — это то, что работает на нас (приносит пользу, доход или сохраняют ценность). «Пассивы» - то, что тянет деньги из вашего кармана (требуют расходов, не принося дохода). Что из предложенного может быть активом и почему?\nВЕЛОСИПЕД, СМАРТФОН, ЗНАНИЕ АНГЛИЙСКОГО ЯЗЫКА, МОДНАЯ СУМКА.', 'Велосипед, смартфон, знание английского языка, модная сумка', 'ВЕЛОСИПЕД – можно использовать для подработки (доставка еды, курьерские услуги). Помогает экономить на транспорте\nСМАРТФОН – можно использовать для учебы и заработка (создание контента и фриланс)\nЗНАНИЕ АНГЛИЙСКОГО ЯЗЫКА – можно переводить тексты за деньги\nМОДНАЯ СУМКА – если ее продать или использовать для создания стиля (например, в блоге) - актив. Если просто пылится в шкафу – пассив', 50, '2025-05-22 12:07:23', '2025-05-22 12:07:23'),
(33, 'В бухгалтерском балансе существует две составляющие: активы и пассивы. Простыми словами «активы» — это то, что работает на нас (приносит пользу, доход или сохраняют ценность). «Пассивы» - то, что тянет деньги из вашего кармана (требуют расходов, не принося дохода). Что из предложенного может быть активом и почему?\nДОМАШНИЙ ПИТОМЕЦ, ПОКУПКА СЛАДОСТЕЙ, КВАРТИРА, КОЛЛЕКЦИЯ МАРОК/МОНЕТ', 'Домашний питомец, квартира, коллекция марок/монет', 'ДОМАШНИЙ ПИТОМЕЦ – можно вести блог о питомце и зарабатывать на этом\nПОКУПКА СЛАДОСТЕЙ – трата денег, вред здоровью\nКВАРТИРА – если сдавать в аренду – актив, а если просто жить и оплачивать ЖКХ\nКОЛЛЕКЦИЯ МАРОК/МОНЕТ – можно дорого продать, если редкая.', 50, '2025-05-22 12:08:39', '2025-05-22 12:08:39');

