) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Дамп данных таблицы `card_t_f_s`
--

INSERT INTO `card_t_f_s` (`id`, `question`, `answer`, `explanation`, `points`, `created_at`, `updated_at`) VALUES
(1, 'Если клиент оплатил товар, но сам товар ему еще не отгружен, это уже считается доходом компании', 0, '__Ложь__, пока это обязательство — аванс', 30, '2025-05-22 10:32:44', '2025-05-22 11:04:43'),
(2, 'Если сотрудник взял деньги в подотчет, но не отчитался, эта сумма считается его доходом', 1, '**Правда**. Если сотрудник взял деньги в подотчет, но не отчитался в установленный срок, эта сумма может быть признана его доходом и облагаться налогом. Отсутствие отчета и документов предполагает, что деньги, скорее всего, были потрачены на личные нужды сотрудника, а не в интересах компании', 30, '2025-05-22 11:04:34', '2025-05-22 11:04:34'),
(3, 'Компания может списать все расходы на представительские мероприятия в налоговом учете', 0, '__Ложь__, есть ограничения по Налоговому кодексу', 30, '2025-05-22 11:06:31', '2025-05-22 11:06:31'),
(4, 'Бухгалтерия занимается только расчетами и не имеет отношения к документам', 0, '__Ложь__, бухгалтер ведет счета, налоги, зарплаты и оформляет документы', 30, '2025-05-22 11:06:56', '2025-05-22 11:06:56'),
(5, 'Если у фирмы много денег в кассе, значит, у нее нет долгов', 0, '__Ложь__, у компании могут быть кредиты и обязательства', 30, '2025-05-22 11:07:19', '2025-05-22 11:07:19'),
(6, 'Деньги в кассе компании — это актив', 1, NULL, 30, '2025-05-22 11:07:57', '2025-05-22 11:07:57'),
(7, 'Списание просроченной дебиторской задолженности уменьшает прибыль компании', 1, NULL, 30, '2025-05-22 11:08:21', '2025-05-22 11:08:21'),
(8, 'Если компания заплатила за товар, но его еще не получила, это актив', 0, '__Ложь__, это аванс поставщику — обязательство перед фирмой', 30, '2025-05-22 11:08:40', '2025-05-22 11:08:40'),
(9, 'Фирма может учитывать личные расходы директора как расходы компании', 0, NULL, 30, '2025-05-22 11:09:02', '2025-05-22 11:09:02'),
(10, 'Все доходы и расходы должны подтверждаться документами', 1, NULL, 30, '2025-05-22 11:09:15', '2025-05-22 11:09:15'),
(11, 'Чем больше доход компании, тем больше у нее прибыль', 0, '__Ложь__, прибыль = доходы – расходы', 30, '2025-05-22 11:12:00', '2025-05-22 11:12:00'),
(12, 'Если сотрудник не получил зарплату вовремя, это не проблема компании', 0, '__Ложь__, задержка зарплаты — это нарушение', 30, '2025-05-22 11:12:24', '2025-05-22 11:12:24'),
(13, 'Если компания купила товар, но не получила чек, она не сможет учесть этот расход', 1, NULL, 30, '2025-05-22 11:12:42', '2025-05-22 11:12:42'),
(14, 'Если компания продает товар дешевле, чем купила, она все равно получает доход', 1, '__Правда__, но это не прибыль, а убыток', 30, '2025-05-22 11:13:04', '2025-05-22 11:13:04'),
(15, 'Если человек получает зарплату «в конверте», он не платит налоги', 1, '__Правда__, но это незаконно', 30, '2025-05-22 11:13:37', '2025-05-22 11:13:37'),
(16, 'Если бизнес не зарабатывает деньги, он не должен сдавать отчеты', 0, '__Ложь__, отчетность обязана быть', 30, '2025-05-22 11:13:54', '2025-05-22 11:13:54'),
(17, 'Клиент заплатил за товар, но не забрал его. Компания может считать деньги своими', 1, '__Правда__, это доход', 30, '2025-05-22 11:14:15', '2025-05-22 11:14:15'),
(18, 'Если фирма ничего не продает, она не может иметь расходов', 0, '__Ложь__, расходы есть всегда: аренда, зарплата, налоги', 30, '2025-05-22 11:14:37', '2025-05-22 11:14:37'),
(19, 'Если поставщик простил долг, считается ли это доходом', 1, NULL, 30, '2025-05-22 11:14:52', '2025-05-22 11:14:52'),
(20, 'Фирма может учитывать расходы на зарплаты сотрудников как свои затраты', 1, NULL, 30, '2025-05-22 11:15:02', '2025-05-22 11:15:02');

